(()=>{const g=__game, {THREE,testCapsule}=__dbg; const out=[];
for (const id of (window.__ids||['E2','E3','E4','E5','E6'])) { g.loadRound(id); g.showScreen(null); g.mode='play'; g.player.release();
 const R0=0.28, a=new THREE.Vector3(), b=new THREE.Vector3(), w=new THREE.Vector3(), c=new THREE.Vector3(), ab=new THREE.Vector3();
 const samples=[]; for(const o of g.course.obstacles){ o.group.traverse(m=>{ if(!m.isMesh||m.material?.blending===2) return; const pos=m.geometry.attributes.position; const stepN=Math.max(1,Math.floor(pos.count/300)); const pts=[]; for(let i=0;i<pos.count;i+=stepN) pts.push(new THREE.Vector3().fromBufferAttribute(pos,i)); samples.push({o,m,pts}); }); }
 const deepest=(p)=>{ const h=p.capsuleHeight(); a.set(p.pos.x,p.pos.y+R0,p.pos.z); b.set(p.pos.x,p.pos.y+h-R0,p.pos.z); let best=null;
   for(const o of g.course.obstacles){ if(Math.abs(o.x-p.pos.x)>8) continue; for(const cc of o.colliders){ const r=testCapsule(a,b,R0,cc); if(r&&(!best||r.depth>best.d)) best={d:r.depth,id:o.id}; } } return best; };
 const R=0.2; const visInside=(p)=>{ const h=p.capsuleHeight(); a.set(p.pos.x,p.pos.y+R,p.pos.z); b.set(p.pos.x,p.pos.y+h-R,p.pos.z); ab.subVectors(b,a); const L=ab.lengthSq();
   for(const s of samples){ if(Math.abs(s.o.x-p.pos.x)>7) continue; let vis=true; for(let q=s.m;q;q=q.parent) if(!q.visible||(q.scale&&q.scale.y<0.3)) vis=false; if(!vis||s.m.geometry.type==='RingGeometry') continue; s.m.updateMatrixWorld(); for(const v of s.pts){ w.copy(v).applyMatrix4(s.m.matrixWorld); const t=Math.max(0,Math.min(1,w.clone().sub(a).dot(ab)/L)); c.copy(a).addScaledVector(ab,t); if(w.distanceTo(c)<R) return s.o.id+':'+(s.m.name||s.m.geometry.type); } } return null; };
 const deep={}, vis={}; let runs=0, frames=0;
 for (const cp of g.course.checkpoints) for (let k=0;k<(id==='E6'?6:12);k++) { g.time=0; g.mode='play'; g.course.time=k*0.57+cp.x*0.05; g.player.respawn(cp); g.player.maxX=cp.x; runs++;
   const act=k%3, at=0.3+(k%7)*0.17;
   g.simulate(3.2,(t,p)=>{ if(p.state==='water') return {}; const d=deepest(p); if(d&&d.d>0.12){ const key=d.id+' '+p.state; deep[key]=(deep[key]||0)+1; }
     if(p.state!=='hit'){ frames++; const v=visInside(p); if(v){ const key=v+' '+p.state; vis[key]=(vis[key]||0)+1; } }
     return {move:1, jump: act===1 && t>at && t<at+0.4, slide: act===2 && t>at && t<at+0.1}; }); }
 out.push(id+' runs '+runs+' frames '+frames+' deep>'+'0.12: '+JSON.stringify(deep)+' visible: '+JSON.stringify(vis)); }
return out})()
